#!/usr/bin/env python3
"""Writes the starter set of ComfyUniversity graphs to studio/university/graphs/<id>.json as {"meta": {...}, "graph": {api format}}.
Every input name below was read from a saved /object_info; scripts/verify_university_graphs.py then runs them through ComfyUI's own validate_prompt, and runs the model-free ones for real on the CPU.
Run it again only to reset these graphs. Graphs written by hand beside them are left alone."""
import json, re, sys
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]; sys.path.insert(0, str(ROOT))
from psn.graph import GraphBuilder
OUT = ROOT / "studio" / "university" / "graphs"
SD15 = "v1-5-pruned-emaonly.safetensors"; SDXL = "sd_xl_base_1.0.safetensors"
POS = "a weathered brass astrolabe on an oak table, warm window light, photograph"; NEG = "blurry, low quality, watermark, text"

def save(id, title, g, runs="model", needs=(), notes=None, about=""):
    OUT.mkdir(parents=True, exist_ok=True)
    (OUT / f"{id}.json").write_text(json.dumps({"meta": {"title": title, "about": about, "runs": runs, "needs": list(needs), "packs": [], "notes": {str(k): v for k, v in (notes or {}).items()}}, "graph": g.to_prompt() if isinstance(g, GraphBuilder) else g}, indent=1, ensure_ascii=False) + "\n")

def base(ckpt=SD15, pos=POS, neg=NEG, w=512, h=512):
    g = GraphBuilder(); ck = g.add("CheckpointLoaderSimple", ckpt_name=ckpt); p = g.add("CLIPTextEncode", text=pos, clip=ck.out(1)); n = g.add("CLIPTextEncode", text=neg, clip=ck.out(1)); e = g.add("EmptyLatentImage", width=w, height=h, batch_size=1)
    return g, ck, p, n, e
def ks(g, model, p, n, lat, seed=424242, steps=20, cfg=7.0, sampler="euler", sched="karras", denoise=1.0): return g.add("KSampler", model=model, seed=seed, steps=steps, cfg=cfg, sampler_name=sampler, scheduler=sched, positive=p, negative=n, latent_image=lat, denoise=denoise)
def out(g, lat, vae, prefix="university"): d = g.add("VAEDecode", samples=lat, vae=vae); s = g.add("SaveImage", images=d, filename_prefix=prefix); return d, s
SD = ["An SD 1.5 checkpoint in models/checkpoints (we used v1-5-pruned-emaonly). Any SD 1.5 file works; pick yours in the loader."]

def nomodel():
    g = GraphBuilder(); a = g.add("EmptyImage", width=512, height=512, batch_size=1, color=0xF5C518); b = g.add("ImageInvert", image=a); g.add("PreviewImage", images=b)
    save("nm_first", "Your first graph, no model needed", g, "cpu", notes={1: "Makes a solid image. The colour is one number, 0xF5C518 here.", 2: "Flips every channel: 1 minus the value.", 3: "An output node. Without it nothing runs."}, about="Three nodes and no model. It runs on any machine in under a second.")
    g = GraphBuilder(); a = g.add("EmptyImage", width=512, height=512, batch_size=1, color=0x224466); b = g.add("ImageBlur", image=a, blur_radius=4, sigma=2.0); g.add("PreviewImage", images=b); g.add("ImageInvert", image=a)
    save("nm_dead_branch", "The branch that never runs", g, "cpu", notes={2: "Feeds the preview, so it runs.", 3: "An output node pulls on its inputs.", 4: "Nothing downstream asks for this, so the engine never runs it."}, about="Queue this and watch node 4 stay idle: no output node needs it.")
    g = GraphBuilder(); bg = g.add("EmptyImage", width=512, height=512, batch_size=1, color=0x101311); fg = g.add("EmptyImage", width=256, height=256, batch_size=1, color=0xF5C518); m = g.add("SolidMask", value=1.0, width=256, height=256); f = g.add("FeatherMask", mask=m, left=64, top=64, right=64, bottom=64); c = g.add("ImageCompositeMasked", destination=bg, source=fg, x=128, y=128, resize_source=False, mask=f); g.add("PreviewImage", images=c); e = g.add("Canny", image=c, low_threshold=0.1, high_threshold=0.3); g.add("PreviewImage", images=e)
    save("nm_mask_canny", "Masks and edges without a model", g, "cpu", notes={3: "A mask is a single-channel picture of numbers from 0 to 1.", 4: "Fades the mask edge in from each side, in pixels.", 5: "Pastes the source where the mask says, blended by its value.", 7: "The same edge detector a Canny ControlNet would take as input."}, about="A soft square, then its edges. Everything a ControlNet preprocessor does starts like this.")
    g = GraphBuilder(); k = g.add("KarrasScheduler", steps=10, sigma_max=14.614642, sigma_min=0.0291675, rho=7.0); e = g.add("ExponentialScheduler", steps=10, sigma_max=14.614642, sigma_min=0.0291675); g.add("PreviewAny", source=k); g.add("PreviewAny", source=e); s = g.add("SplitSigmas", sigmas=k, step=5); g.add("PreviewAny", source=s.out(0)); g.add("PreviewAny", source=s.out(1))
    save("nm_sigmas", "Print a schedule, no model needed", g, "cpu", notes={1: "These two scheduler nodes take no MODEL: they only need the range.", 3: "PreviewAny shows whatever arrives as text. Here, the list of noise levels.", 5: "Cuts one schedule in two at a step. Two samplers can then run the two halves."}, about="Schedules are plain lists of numbers. Print them and read them.")
    g = GraphBuilder(); a = g.add("EmptyLatentImage", width=512, height=512, batch_size=1); b = g.add("LatentUpscale", samples=a, upscale_method="nearest-exact", width=1024, height=1024, crop="disabled"); c = g.add("LatentMultiply", samples=b, multiplier=0.5); g.add("PreviewAny", source=c)
    save("nm_latent_ops", "Latent operations you can run on a CPU", g, "cpu", notes={1: "An all-zero tensor, one eighth the pixel size on each side.", 2: "Resizes the numbers directly. It is not an image upscale.", 3: "Multiplies every value. Sampling is sensitive to this."}, about="Latents are tensors. Print one and see.")
    g = GraphBuilder(); a = g.add("EmptyAudio", duration=1.0, sample_rate=44100, channels=2); b = g.add("AudioAdjustVolume", audio=a, volume=-6); g.add("SaveAudio", audio=b, filename_prefix="audio/university")
    save("nm_audio", "A second of silence, saved", g, "cpu", notes={1: "An AUDIO value is a waveform tensor and a sample rate.", 2: "Volume is in decibels on this node.", 3: "Writes a file to output/audio."}, about="The audio types and save nodes, with no model.")
    g = GraphBuilder(); a = g.add("EmptyImage", width=256, height=256, batch_size=8, color=0x27E07F); b = g.add("CreateVideo", images=a, fps=8.0); g.add("SaveVideo", video=b, filename_prefix="video/university", format="auto", codec="auto")
    save("nm_video", "One second of video, no model", g, "cpu", notes={1: "batch_size is the frame count: a video is an image batch.", 2: "Bundles frames, frame rate and optional audio into one VIDEO value.", 3: "Encodes and writes the file."}, about="Eight frames at 8 frames per second.")
    g = GraphBuilder(); a = g.add("PrimitiveString", value="a weathered brass astrolabe"); b = g.add("PrimitiveString", value="warm window light"); c = g.add("StringConcatenate", string_a=a, string_b=b, delimiter=", "); g.add("PreviewAny", source=c)
    save("nm_text", "Prompts are strings you can wire", g, "cpu", notes={3: "Joins the two strings. Feed this to a text encoder's text input.", 4: "Shows the result as text."}, about="Build a prompt out of parts before any model is loaded.")

def sd():
    g, ck, p, n, e = base(); s = ks(g, ck.out(0), p, n, e); out(g, s, ck.out(2))
    save("sd15_txt2img", "The classic text-to-image graph", g, needs=SD, notes={1: "Reads one file and hands out three things: the denoiser, the text encoder and the VAE.", 2: "Turns the prompt into conditioning.", 3: "The negative prompt. It is the other half of CFG.", 4: "An empty latent. KSampler adds the noise.", 5: "Runs the sampling loop.", 6: "Latent to pixels.", 7: "Writes the PNG."}, about="Seven nodes. Almost every image graph is this with parts swapped.")
    g, ck, p, n, _ = base(); i = g.add("LoadImage", image="example.png"); v = g.add("VAEEncode", pixels=i, vae=ck.out(2)); s = ks(g, ck.out(0), p, n, v, denoise=0.6); out(g, s, ck.out(2))
    save("sd15_img2img", "Image to image: denoise below 1", g, needs=SD, notes={5: "A picture of your own in ComfyUI's input folder.", 6: "Pixels to latent.", 7: "denoise 0.6 starts from a noised copy of your picture and runs the last part of the schedule."}, about="The same sampler with a starting picture.")
    g, ck, p, n, _ = base(); i = g.add("LoadImage", image="example.png"); v = g.add("VAEEncode", pixels=i, vae=ck.out(2)); m = g.add("SetLatentNoiseMask", samples=v, mask=i.out(1)); s = ks(g, ck.out(0), p, n, m, denoise=0.8); out(g, s, ck.out(2))
    save("sd15_inpaint", "Inpaint with a noise mask", g, needs=SD, notes={5: "Paint a mask in the image editor. It arrives on the second output.", 7: "Attaches the mask to the latent. The sampler keeps unmasked areas pinned to the original."}, about="Regenerate part of a picture and keep the rest.")
    g, ck, p, n, _ = base(); i = g.add("LoadImage", image="example.png"); v = g.add("VAEEncodeForInpaint", pixels=i, vae=ck.out(2), mask=i.out(1), grow_mask_by=6); s = ks(g, ck.out(0), p, n, v, denoise=1.0); out(g, s, ck.out(2))
    save("sd15_inpaint_vae", "Inpaint with VAEEncodeForInpaint", g, needs=["An inpainting checkpoint is the usual partner for this node. Pick yours in the loader."], notes={6: "Greys out the masked pixels before encoding, grows the mask and attaches it. Meant for denoise 1."}, about="The other inpaint route. It blanks the area first, so it needs full denoise.")
    g, ck, p, n, e = base(); a = ks(g, ck.out(0), p, n, e, steps=20); u = g.add("LatentUpscale", samples=a, upscale_method="nearest-exact", width=768, height=768, crop="disabled"); b = ks(g, ck.out(0), p, n, u, steps=14, denoise=0.5, seed=424243); out(g, b, ck.out(2))
    save("sd15_hires", "Two passes: draft, then refine bigger", g, needs=SD, notes={5: "The draft at the size the model likes.", 6: "Resize in latent space.", 7: "Half denoise repaints detail and keeps the composition."}, about="The usual way to get more pixels than the model was trained on.")
    g, ck, p, n, e = base(); a = g.add("KSamplerAdvanced", model=ck.out(0), add_noise="enable", noise_seed=424242, steps=20, cfg=7.0, sampler_name="euler", scheduler="karras", positive=p, negative=n, latent_image=e, start_at_step=0, end_at_step=12, return_with_leftover_noise="enable"); b = g.add("KSamplerAdvanced", model=ck.out(0), add_noise="disable", noise_seed=0, steps=20, cfg=7.0, sampler_name="dpmpp_2m", scheduler="karras", positive=p, negative=n, latent_image=a, start_at_step=12, end_at_step=10000, return_with_leftover_noise="disable"); out(g, b, ck.out(2))
    save("sd15_two_stage", "Two samplers share one schedule", g, needs=SD, notes={5: "Runs steps 0 to 12 and keeps the leftover noise.", 6: "Adds no new noise, then runs steps 12 to 20 with a different solver."}, about="KSamplerAdvanced hands the job over part-way.")
    g, ck, p, n, e = base(); nz = g.add("RandomNoise", noise_seed=424242); gd = g.add("CFGGuider", model=ck.out(0), positive=p, negative=n, cfg=7.0); sa = g.add("KSamplerSelect", sampler_name="euler"); si = g.add("BasicScheduler", model=ck.out(0), scheduler="karras", steps=20, denoise=1.0); s = g.add("SamplerCustomAdvanced", noise=nz, guider=gd, sampler=sa, sigmas=si, latent_image=e); out(g, s.out(0), ck.out(2))
    save("sd15_custom", "KSampler taken apart", g, needs=SD, notes={5: "Where the noise comes from.", 6: "How model calls become one prediction: here, CFG.", 7: "The update rule.", 8: "The list of noise levels.", 9: "Does what KSampler does, from these four separate parts."}, about="The five parts of a KSampler as separate nodes, so you can swap each one.")
    g, ck, p, n, e = base(); nz = g.add("RandomNoise", noise_seed=424242); gd = g.add("CFGGuider", model=ck.out(0), positive=p, negative=n, cfg=7.0); sa = g.add("KSamplerSelect", sampler_name="euler"); si = g.add("KarrasScheduler", steps=20, sigma_max=14.614642, sigma_min=0.0291675, rho=3.0); s = g.add("SamplerCustomAdvanced", noise=nz, guider=gd, sampler=sa, sigmas=si, latent_image=e); out(g, s.out(0), ck.out(2))
    save("sd15_karras_rho", "Bend the schedule yourself", g, needs=SD, notes={8: "rho 3 spends steps differently from the default 7. Try the numbers from the sigma lab here."}, about="A scheduler node with its dial exposed.")
    g, ck, p, n, e = base(); l = g.add("LoraLoader", model=ck.out(0), clip=ck.out(1), lora_name="your_lora.safetensors", strength_model=0.8, strength_clip=0.8); p2 = g.add("CLIPTextEncode", text=POS, clip=l.out(1)); n2 = g.add("CLIPTextEncode", text=NEG, clip=l.out(1)); s = ks(g, l.out(0), p2, n2, e); out(g, s, ck.out(2))
    save("sd15_lora", "Load a LoRA", g, needs=SD + ["A LoRA for SD 1.5 in models/loras, made by you or by someone you trust."], notes={5: "Patches the denoiser and the text encoder. Everything after it must use its outputs.", 6: "Encoded with the patched text encoder, not the original."}, about="The most common mistake is wiring the original CLIP past the loader.")
    g, ck, p, n, e = base(); i = g.add("LoadImage", image="example.png"); c = g.add("Canny", image=i, low_threshold=0.4, high_threshold=0.8); cn = g.add("ControlNetLoader", control_net_name="control_v11p_sd15_canny.safetensors"); ap = g.add("ControlNetApplyAdvanced", positive=p, negative=n, control_net=cn, image=c, strength=0.9, start_percent=0.0, end_percent=0.8); s = ks(g, ck.out(0), ap.out(0), ap.out(1), e); out(g, s, ck.out(2))
    save("sd15_controlnet", "ControlNet from a Canny edge map", g, needs=SD + ["A Canny ControlNet for SD 1.5 in models/controlnet."], notes={6: "Edges from your picture. Preview this before you trust it.", 8: "Attaches the control to both conditionings. end_percent 0.8 lets the last fifth of the schedule run free."}, about="Shape comes from the edges. Everything else comes from the prompt.")
    g, ck, p, n, e = base(); i = g.add("LoadImage", image="depth_map.png"); cn = g.add("ControlNetLoader", control_net_name="control_v11f1p_sd15_depth.safetensors"); ap = g.add("ControlNetApplyAdvanced", positive=p, negative=n, control_net=cn, image=i, strength=0.8, start_percent=0.0, end_percent=1.0); s = ks(g, ck.out(0), ap.out(0), ap.out(1), e); out(g, s, ck.out(2))
    save("sd15_controlnet_depth", "ControlNet from a depth map", g, needs=SD + ["A depth ControlNet for SD 1.5 in models/controlnet, and a depth map picture in the input folder."], notes={5: "A depth map is a grey picture. Check which end is near: the two conventions look like negatives of each other.", 7: "Same node as Canny. Only the model and the picture change."}, about="Depth controls layout and leaves surfaces to the prompt.")
    for id, cls, kw, title, note, about in (("sd15_rescale", "RescaleCFG", {"multiplier": 0.7}, "RescaleCFG", "Patches how CFG is computed. It pulls the result's spread back towards the positive prediction's.", "A model patch sits between the loader and the sampler."), ("sd15_pag", "PerturbedAttentionGuidance", {"scale": 3.0}, "Perturbed-attention guidance", "Adds a third model call with self-attention deliberately broken.", "Guidance against a damaged version of the model's own output."), ("sd15_sag", "SelfAttentionGuidance", {"scale": 0.5, "blur_sigma": 2.0}, "Self-attention guidance", "Blurs where self-attention looks hardest, and guides away from that.", "Guidance based on where the model is attending."), ("sd15_cfgnorm", "CFGNorm", {"strength": 1.0}, "CFGNorm", "Caps how large the guided prediction may grow compared to the positive one.", "Norm control at high CFG.")):
        g, ck, p, n, e = base(); m = g.add(cls, model=ck.out(0), **kw); s = ks(g, m, p, n, e, cfg=14.0 if id in ("sd15_rescale", "sd15_cfgnorm") else 7.0); out(g, s, ck.out(2))
        save(id, title, g, needs=SD, notes={5: note}, about=about)
    g, ck, p, n, e = base(); em = g.add("CLIPTextEncode", text="", clip=ck.out(1)); nz = g.add("RandomNoise", noise_seed=424242); gd = g.add("PerpNegGuider", model=ck.out(0), positive=p, negative=n, empty_conditioning=em, cfg=7.0, neg_scale=1.0); sa = g.add("KSamplerSelect", sampler_name="euler"); si = g.add("BasicScheduler", model=ck.out(0), scheduler="karras", steps=20, denoise=1.0); s = g.add("SamplerCustomAdvanced", noise=nz, guider=gd, sampler=sa, sigmas=si, latent_image=e); out(g, s.out(0), ck.out(2))
    save("sd15_perpneg", "Perp-Neg guider", g, needs=SD, notes={5: "An empty prompt: Perp-Neg measures both prompts against this.", 7: "A guider, so it needs SamplerCustomAdvanced rather than KSampler."}, about="Keeps only the part of the negative that does not fight the positive.")
    for id, cls, title, note, about in (("sd15_cond_combine", "ConditioningCombine", "Two prompts: Combine", "Keeps both as separate entries. The model is called for each and the results are averaged by weight.", "Separate predictions, blended."), ("sd15_cond_concat", "ConditioningConcat", "Two prompts: Concat", "Joins the token rows into one longer sequence. One model call attends to all of them.", "One longer sequence.")):
        g = GraphBuilder(); ck = g.add("CheckpointLoaderSimple", ckpt_name=SD15); a = g.add("CLIPTextEncode", text="a brass astrolabe", clip=ck.out(1)); b = g.add("CLIPTextEncode", text="a stack of old sea charts", clip=ck.out(1)); n = g.add("CLIPTextEncode", text=NEG, clip=ck.out(1)); e = g.add("EmptyLatentImage", width=512, height=512, batch_size=1)
        c = g.add(cls, **({"conditioning_1": a, "conditioning_2": b} if cls == "ConditioningCombine" else {"conditioning_to": a, "conditioning_from": b})); s = ks(g, ck.out(0), c, n, e); out(g, s, ck.out(2)); save(id, title, g, needs=SD, notes={6: note}, about=about)
    g = GraphBuilder(); ck = g.add("CheckpointLoaderSimple", ckpt_name=SD15); a = g.add("CLIPTextEncode", text="a brass astrolabe", clip=ck.out(1)); b = g.add("CLIPTextEncode", text="a stack of old sea charts", clip=ck.out(1)); n = g.add("CLIPTextEncode", text=NEG, clip=ck.out(1)); e = g.add("EmptyLatentImage", width=512, height=512, batch_size=1); c = g.add("ConditioningAverage", conditioning_to=a, conditioning_from=b, conditioning_to_strength=0.6); s = ks(g, ck.out(0), c, n, e); out(g, s, ck.out(2))
    save("sd15_cond_average", "Two prompts: Average", g, needs=SD, notes={6: "Blends the two sets of embeddings value by value, before any model call."}, about="One blended embedding.")
    g = GraphBuilder(); ck = g.add("CheckpointLoaderSimple", ckpt_name=SD15); a = g.add("CLIPTextEncode", text="a calm sea at dawn", clip=ck.out(1)); b = g.add("CLIPTextEncode", text="a small wooden boat", clip=ck.out(1)); n = g.add("CLIPTextEncode", text=NEG, clip=ck.out(1)); e = g.add("EmptyLatentImage", width=768, height=512, batch_size=1); ar = g.add("ConditioningSetArea", conditioning=b, width=256, height=256, x=256, y=200, strength=1.0); c = g.add("ConditioningCombine", conditioning_1=a, conditioning_2=ar); s = ks(g, ck.out(0), c, n, e); out(g, s, ck.out(2))
    save("sd15_cond_area", "A prompt for part of the picture", g, needs=SD, notes={6: "This prompt only applies inside the box. Sizes are in pixels and are converted to latent cells.", 7: "The whole-picture prompt and the boxed one, side by side."}, about="Regional prompting with core nodes.")
    g = GraphBuilder(); ck = g.add("CheckpointLoaderSimple", ckpt_name=SD15); a = g.add("CLIPTextEncode", text="an old stone tower", clip=ck.out(1)); b = g.add("CLIPTextEncode", text="covered in moss and vines", clip=ck.out(1)); n = g.add("CLIPTextEncode", text=NEG, clip=ck.out(1)); e = g.add("EmptyLatentImage", width=512, height=512, batch_size=1); ra = g.add("ConditioningSetTimestepRange", conditioning=a, start=0.0, end=0.5); rb = g.add("ConditioningSetTimestepRange", conditioning=b, start=0.5, end=1.0); c = g.add("ConditioningCombine", conditioning_1=ra, conditioning_2=rb); s = ks(g, ck.out(0), c, n, e); out(g, s, ck.out(2))
    save("sd15_cond_time", "Change the prompt part-way through", g, needs=SD, notes={6: "Active for the first half of the schedule, by percent of model sigmas.", 7: "Active for the second half.", 8: "Holds both. The sampler picks by the current noise level."}, about="Layout from one prompt, detail from another.")
    g, ck, p, n, e = base(); s = ks(g, ck.out(0), p, n, e); d = g.add("VAEDecodeTiled", samples=s, vae=ck.out(2), tile_size=512, overlap=64, temporal_size=64, temporal_overlap=8); g.add("SaveImage", images=d, filename_prefix="university")
    save("sd15_tiled_vae", "Decode in tiles when VRAM runs short", g, needs=SD, notes={6: "Decodes overlapping pieces and blends them. Slower, much less memory."}, about="The first thing to try when decoding runs out of memory.")
    g, ck, p, n, e = base(); s = ks(g, ck.out(0), p, n, e); d, sv = out(g, s, ck.out(2)); u = g.add("UpscaleModelLoader", model_name="your_upscaler.safetensors"); im = g.add("ImageUpscaleWithModel", upscale_model=u, image=d); g.add("SaveImage", images=im, filename_prefix="university_up")
    save("sd15_upscale", "Upscale pixels with a model", g, needs=SD + ["An upscale model in models/upscale_models."], notes={9: "Works on pixels, after decoding. Its scale is fixed by the model file."}, about="Pixel upscaling adds learned detail without a prompt.")
    g = GraphBuilder(); a = g.add("CheckpointLoaderSimple", ckpt_name=SD15); b = g.add("CheckpointLoaderSimple", ckpt_name="another_sd15_model.safetensors"); m = g.add("ModelMergeSimple", model1=a, model2=b, ratio=0.5); g.add("CheckpointSave", model=m, clip=a.out(1), vae=a.out(2), filename_prefix="checkpoints/merged")
    save("sd15_merge", "Merge two checkpoints", g, needs=["Two checkpoints of the same architecture."], notes={3: "Blends every matching weight. Merge unquantized files, then quantize the result.", 4: "Writes the merged file. It is an output node with no outputs."}, about="A blend, written to disk.")
    g = GraphBuilder(); ck = g.add("CheckpointLoaderSimple", ckpt_name=SD15); ds = g.add("LoadImageTextDataSetFromFolder", folder="my_dataset"); mk = g.add("MakeTrainingDataset", images=ds, texts=ds.out(1), vae=ck.out(2), clip=ck.out(1)); tr = g.add("TrainLoraNode", model=ck, latents=mk, positive=mk.out(1), batch_size=1, grad_accumulation_steps=1, steps=300, learning_rate=0.0005, rank=8, optimizer="AdamW", loss_function="MSE", seed=0, training_dtype="bf16", lora_dtype="bf16", quantized_backward=False, algorithm="LoRA", gradient_checkpointing=True, checkpoint_depth=1, offloading=False, existing_lora="[None]", bucket_mode=False, bypass_mode=False); g.add("SaveLoRA", lora=tr, prefix="loras/university", steps=tr.out(2)); g.add("LossGraphNode", loss=tr.out(1), filename_prefix="university_loss")
    save("sd15_train_lora", "Train a LoRA with core nodes", g, needs=SD + ["A folder of pictures with matching .txt captions in the input folder, named my_dataset."], notes={2: "Pairs each picture with its caption.", 3: "Encodes pictures to latents and captions to conditioning, once, ahead of training.", 4: "The training loop. Rank sets the file size. It needs a free GPU.", 5: "Writes the LoRA."}, about="The path our Train page uses, in six nodes.")
    g, ck, p, n, e = base(SDXL, w=1024, h=1024); s = ks(g, ck.out(0), p, n, e, cfg=6.0, sampler="dpmpp_2m", sched="karras"); out(g, s, ck.out(2))
    save("sdxl_txt2img", "SDXL text to image", g, needs=["An SDXL checkpoint."], notes={1: "Same node. It reads the file and works out the architecture.", 4: "SDXL's training size was about 1024 by 1024."}, about="Same graph, different file and size.")
    g = GraphBuilder(); ck = g.add("CheckpointLoaderSimple", ckpt_name="sd3.5_medium.safetensors"); tr = g.add("TripleCLIPLoader", clip_name1="clip_l.safetensors", clip_name2="clip_g.safetensors", clip_name3="t5xxl_fp16.safetensors"); m = g.add("ModelSamplingSD3", model=ck, shift=3.0); p = g.add("CLIPTextEncode", text=POS, clip=tr); n = g.add("CLIPTextEncode", text="", clip=tr); e = g.add("EmptySD3LatentImage", width=1024, height=1024, batch_size=1); s = ks(g, m, p, n, e, cfg=4.5, sched="simple"); out(g, s, ck.out(2))
    save("sd35_flow", "A flow model: SD 3.5", g, needs=["SD 3.5 Medium and its three text encoders."], notes={3: "Sets how the flow schedule is bent. Larger shift spends more steps at high noise.", 6: "SD3 latents have 16 channels, so it needs its own empty latent node."}, about="Flow models use a shift and a different latent.")
    g = GraphBuilder(); ck = g.add("ImageOnlyCheckpointLoader", ckpt_name="hunyuan3d-dit-v2_fp16.safetensors"); i = g.add("LoadImage", image="example.png"); ce = g.add("CLIPVisionEncode", clip_vision=ck.out(1), image=i, crop="center"); c = g.add("Hunyuan3Dv2Conditioning", clip_vision_output=ce); e = g.add("EmptyLatentHunyuan3Dv2", resolution=3072, batch_size=1); s = ks(g, ck.out(0), c.out(0), c.out(1), e, steps=30, cfg=5.5, sched="normal"); d = g.add("VAEDecodeHunyuan3D", samples=s, vae=ck.out(2), num_chunks=8000, octree_resolution=256); me = g.add("VoxelToMeshBasic", voxel=d, threshold=0.6); g.add("SaveGLB", mesh=me, filename_prefix="3d/university")
    save("hunyuan3d_mesh", "Image to mesh with core nodes", g, needs=["A Hunyuan3D 2 checkpoint in models/checkpoints. Not on our test box, so we validated this graph but did not run it."], notes={1: "This loader returns a vision encoder rather than a text encoder.", 7: "Decodes the latent to a grid of occupancy values.", 8: "Turns the grid into triangles at a threshold.", 9: "Writes a GLB you can open in the 3D tab."}, about="A sampler again, then a mesh step at the end.")

def workflows():
    """Concrete copies of the studio's own video and music templates, with placeholders filled, so they open as they are."""
    fills = {"prompt": POS, "negative": NEG, "fps": 24, "width": 832, "height": 480, "frames": 81, "length": 81, "seed": 424242, "steps": 20, "cfg": 5.0, "image": "example.png", "seconds": 30, "duration": 30, "caption": "warm lo-fi piano, slow, rainy afternoon", "lyrics": "[instrumental]", "turbo": False, "aspect": "16:9 (Widescreen)", "megapixels": 0.5, "unet": "flux-2-klein-4b-fp8.safetensors"}
    for src, id, title, need, about in (("h3_t2v_api", "wf_h3_t2v", "MiniMax H3: text to video", "MiniMax H3 weights: its model, text encoder and both VAEs.", "The studio's real H3 graph."), ("ltx25_core_t2v_api", "wf_ltx25_t2v", "LTX-2.5: text to video", "LTX-2.5 weights.", "The studio's real LTX graph."), ("wan22_5b_t2v_api", "wf_wan22_t2v", "Wan 2.2 5B: text to video", "Wan 2.2 TI2V 5B weights.", "The studio's real Wan graph."), ("music3_api", "wf_music3", "MiniMax Music 3", "MiniMax Music 3 weights.", "The studio's real music graph."), ("flux2_klein4b_t2i_api", "wf_flux2_klein", "FLUX.2 Klein: text to image", "FLUX.2 Klein 4B weights.", "A modern image graph: guider, sampler and schedule as parts.")):
        t = (ROOT / "workflows" / f"{src}.json").read_text(); miss = set()
        def rep(m):
            k = m.group(1); v = fills.get(k)
            if v is None: miss.add(k); return m.group(0)
            return str(v)
        # A placeholder as a whole JSON string becomes a number when the value is one.
        t = re.sub(r'"\$\{(\w+)\}"', lambda m: json.dumps(fills[m.group(1)]) if m.group(1) in fills else m.group(0), t); t = re.sub(r"\$\{(\w+)\}", rep, t)
        if miss: print(id, "unfilled:", sorted(miss))
        g = json.loads(t)
        if id == "wf_ltx25_t2v": del g["9"]; g["10"]["inputs"]["frame_rate"] = 24  # the template's LTXFloatToInt is from a pack and only turned 24 into an integer
        save(id, title, g, needs=[need], about=about)

if __name__ == "__main__": nomodel(); sd(); workflows(); print(len(list(OUT.glob("*.json"))), "graphs")
